import { NextRequest, NextResponse } from 'next/server';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { getAIUsageStats, incrementAIUsage, D1Database } from '@/lib/db';

export const runtime = 'edge';

const MODEL_ID = "gemma-3-27b-it";
const RPM_LIMIT = 25; // 安全阈值，官方 30
const TPM_LIMIT = 12000; // 安全阈值，官方 15000

import { RemoteD1Client } from '@/lib/remoteD1';

// 获取 D1 数据库绑定
function getDB(request: NextRequest): D1Database | null {
    // 1. 尝试从 process.env 获取 (Cloudflare Pages nodejs_compat 标准方式)
    if (typeof process !== 'undefined' && process.env?.DB) {
        return process.env.DB as unknown as D1Database;
    }

    // 2. 尝试从 globalThis 获取
    const globalDB = (globalThis as unknown as { DB: D1Database }).DB;
    if (globalDB) return globalDB;

    // 3. 尝试从 request.env 获取 (部分环境支持)
    const env = (request as unknown as { env: { DB: D1Database } }).env;
    if (env?.DB) return env.DB;

    // 4. 本地开发环境：尝试连接远程 D1 (增强容错处理)
    // 处理可能存在的空格问题 (通过遍历 process.env 键值对)
    let apiToken = "";
    let accountId = "";
    let dbId = "";

    for (const [key, value] of Object.entries(process.env)) {
        const trimmedKey = key.trim();
        const trimmedValue = value?.trim() || "";
        if (trimmedKey === 'CLOUDFLARE_API_TOKEN') apiToken = trimmedValue;
        if (trimmedKey === 'CLOUDFLARE_ACCOUNT_ID') accountId = trimmedValue;
        if (trimmedKey === 'CLOUDFLARE_D1_ID') dbId = trimmedValue;
    }

    if (apiToken && accountId && dbId) {
        console.log('[AI API] Local Dev: Initializing Remote D1 Client');
        return new RemoteD1Client(apiToken, accountId, dbId);
    }

    console.warn('[AI API] DB not found. Env check:', {
        hasToken: !!apiToken,
        hasAccount: !!accountId,
        hasDb: !!dbId
    });

    return null;
}

export async function POST(req: NextRequest, ctx: any) {
    try {
        const { prompt, systemPrompt, temperature = 0.85, topP = 0.95, cacheKey } = await req.json();

        if (!prompt) {
            return NextResponse.json({ error: 'Prompt is required' }, { status: 400 });
        }

        const db = getDB(req);
        if (!db) {
            console.error('[AI API] D1 Database binding "DB" is missing');
            return NextResponse.json({ error: 'Database not available' }, { status: 500 });
        }

        // 0. 如果有 cacheKey，先尝试直接从后端读取缓存 (多一层保险)
        if (cacheKey) {
            const cached = await db.prepare('SELECT value FROM ai_cache WHERE key = ?').bind(cacheKey).first<{ value: string }>();
            if (cached) {
                console.log(`[AI API] Backend Cache Hit: ${cacheKey}`);
                return NextResponse.json({ success: true, text: cached.value, fromCache: true });
            }
        }

        // 1. 预估 Token 消耗 (保守估计)
        // 中日文约 1.5 - 2 token/char，英文约 0.3 - 0.5
        const estInputTokens = Math.ceil((prompt.length + (systemPrompt?.length || 0)) * 1.5);

        // 2. 检查配额
        // 获取当前分钟 Key (UTC 时间)
        const now = new Date();
        const minuteKey = `${now.toISOString().slice(0, 16).replace('T', ' ')}`; // YYYY-MM-DD HH:mm

        const stats = await getAIUsageStats(db, MODEL_ID, minuteKey);
        const currentRPM = stats?.request_count || 0;
        const currentTPM = stats?.token_count || 0;

        if (currentRPM >= RPM_LIMIT || currentTPM + estInputTokens > TPM_LIMIT) {
            console.warn(`[AI RateLimit] Limit hit: RPM ${currentRPM}/${RPM_LIMIT}, TPM ${currentTPM}/${TPM_LIMIT} (est ${estInputTokens})`);
            return NextResponse.json({
                error: 'Too Many Requests',
                message: '老师现在太忙了，请等一分钟后再试（流量配额已接近限制）。',
                retryAfter: 60
            }, { status: 429 });
        }

        // 3. 预先占位增加计数 (防止瞬时并发绕过检查)
        try {
            await incrementAIUsage(db, MODEL_ID, minuteKey, 1, estInputTokens);
        } catch (_e) {
            console.error('[AI Usage] Failed to increment initial usage', _e);
            // 继续执行，防止数据库错误阻断 AI 服务，但记录日志
        }

        // 4. 调用 Gemini
        // 优先使用后端独有的 GEMINI_API_KEY，如果没有则尝试 NEXT_PUBLIC_GEMINI_API_KEY
        const apiKey = process.env.GEMINI_API_KEY || process.env.NEXT_PUBLIC_GEMINI_API_KEY || "";
        if (!apiKey) {
            return NextResponse.json({ error: 'AI API Key is missing' }, { status: 500 });
        }

        const genAI = new GoogleGenerativeAI(apiKey);
        const model = genAI.getGenerativeModel({
            model: MODEL_ID,
            generationConfig: {
                temperature,
                topP,
                maxOutputTokens: 2000,
            }
        });

        // 合并 Prompt (Gemma 3 推荐将 System Instructions 放入 Prompt 开头)
        const fullPrompt = systemPrompt ? `${systemPrompt}\n\nUser Question:\n${prompt}` : prompt;

        // 流式调用
        const result = await model.generateContentStream(fullPrompt);

        // 5. 准备流式响应
        const encoder = new TextEncoder();
        let fullText = "";

        // 用于控制流的状态
        let isStreamClosed = false;

        const responseStream = new ReadableStream({
            async start(controller) {
                // 定义后台处理逻辑 (唯一的一次流消费)
                const processStream = async () => {
                    try {
                        for await (const chunk of result.stream) {
                            const text = chunk.text();
                            if (text) {
                                fullText += text;
                                // 如果客户端未断开，发送数据
                                if (!isStreamClosed) {
                                    try {
                                        controller.enqueue(encoder.encode(text));
                                    } catch (e) {
                                        // 可能是客户端已断开
                                        console.warn('[AI API] Client disconnected, marking stream closed.');
                                        isStreamClosed = true;
                                    }
                                }
                            }
                        }

                        // 流结束，关闭控制器
                        if (!isStreamClosed) {
                            controller.close();
                            isStreamClosed = true;
                        }

                        // 6. 后台统计与缓存 (在流结束后执行)
                        try {
                            const response = await result.response;
                            const usage = response.usageMetadata;

                            // 更新 Token 统计
                            if (usage) {
                                const actualTotal = usage.totalTokenCount;
                                const correction = actualTotal - estInputTokens;
                                if (correction !== 0) {
                                    await incrementAIUsage(db, MODEL_ID, minuteKey, 0, correction);
                                }
                                console.log(`[AI Usage] Minute: ${minuteKey}, Actual total: ${actualTotal} (est was ${estInputTokens})`);
                            }

                            // 写入缓存
                            if (cacheKey && fullText) {
                                await db.prepare(`
                                    INSERT OR REPLACE INTO ai_cache (key, value, created_at)
                                    VALUES (?, ?, ?)
                                `).bind(cacheKey, fullText, new Date().toISOString()).run();
                                console.log(`[AI API] Background Cache Saved: ${cacheKey}`);
                            }
                        } catch (statsError) {
                            console.error('[AI API] Stats/Cache Error:', statsError);
                        }

                    } catch (err: unknown) {
                        console.error('[AI API] Stream Processing Error:', err);
                        if (!isStreamClosed) {
                            controller.error(err);
                            isStreamClosed = true;
                        }
                    }
                };

                // 启动处理任务
                const task = processStream();

                // 使用 waitUntil 保持后台运行
                if (ctx && typeof ctx.waitUntil === 'function') {
                    ctx.waitUntil(task);
                } else {
                    // 非 Cloudflare 环境下等待任务完成 (防止过早终止)
                    await task;
                }
            },
            cancel() {
                isStreamClosed = true;
                console.log('[AI API] Stream cancelled by client.');
            }
        });

        return new Response(responseStream, {
            headers: {
                'Content-Type': 'text/plain; charset=utf-8',
                'Transfer-Encoding': 'chunked',
            },
        });

    } catch (error: unknown) {
        console.error('[AI API] Fatal Error:', error);
        return NextResponse.json(
            { error: 'Internal Server Error', details: error instanceof Error ? error.message : String(error) },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';

export const runtime = 'edge';

/**
 * Yomitan Dictionary API
 * 
 * Modified for Edge Runtime: Fetches static JSON files via HTTP instead of file system.
 */

interface YomitanEntry {
    term: string;
    reading: string;
    defTags: string;
    rules: string;
    score: number;
    definitions: string[];
    sequence: number;
    termTags: string;
}

interface DictionaryResult {
    term: string;
    reading: string;
    partOfSpeech: string;
    definitions: string[];
    source: string;
}

// Format definition text
function formatDefinition(def: string): string {
    return def
        .replace(/▾/g, '')
        .replace(/⟨([^⟩]+)⟩/g, '【$1】')
        .trim();
}

// Parsed from raw array
function parseEntry(entry: unknown[]): YomitanEntry {
    return {
        term: entry[0] as string,
        reading: entry[1] as string,
        defTags: entry[2] as string,
        rules: entry[3] as string,
        score: entry[4] as number,
        definitions: entry[5] as string[],
        sequence: entry[6] as number,
        termTags: entry[7] as string
    };
}

function inferPartOfSpeech(rules: string, def: string): string {
    if (rules.includes('v5')) return '五段动词';
    if (rules.includes('v1')) return '一段动词';
    if (rules.includes('vs')) return 'サ变动词';
    if (rules.includes('vk')) return 'カ变动词';
    if (rules.includes('adj-i')) return 'い形容词';
    if (rules.includes('adj-na')) return 'な形容词';
    const posMatch = def.match(/【([^】]+)】/);
    if (posMatch) {
        const pos = posMatch[1];
        if (pos.includes('名')) return '名词';
        if (pos.includes('動') || pos.includes('动')) return '动词';
        if (pos.includes('形')) return '形容词';
        if (pos.includes('副')) return '副词';
        return pos;
    }
    return '';
}

function convertToResult(entry: YomitanEntry): DictionaryResult {
    const firstDef = entry.definitions[0] || '';
    return {
        term: entry.term,
        reading: entry.reading || entry.term,
        partOfSpeech: inferPartOfSpeech(entry.rules, firstDef),
        definitions: entry.definitions.map(formatDefinition),
        source: '明鏡日汉双解辞典'
    };
}

export async function GET(request: NextRequest) {
    const searchParams = request.nextUrl.searchParams;
    const keyword = searchParams.get('keyword');

    if (!keyword) {
        return NextResponse.json({ error: 'Keyword is required' }, { status: 400 });
    }

    try {
        const origin = request.nextUrl.origin;
        const results: DictionaryResult[] = [];
        const seen = new Set<string>();

        // Optimization 1: Sequential batch fetching + Early exit
        // Instead of fetching all 17 at once, we fetch in batches or sequentially to avoid hitting subrequest limits.
        // Since we are looking for a specific keyword, we can stop AS SOON AS WE FIND IT.
        // Files are term_bank_1.json to term_bank_18.json (based on loader checks).
        const maxBanks = 20; // Safety limit

        // Optimistic Strategy: Check banks sequentially. 
        // Note: In a real production app without an index, this is still O(N) but better than 17 parallels crashing the worker.
        // We will do small batches of 3 to balance speed and stability.

        for (let i = 1; i <= maxBanks; i += 4) {
            const batch = [i, i + 1, i + 2, i + 3].filter(n => n <= maxBanks);
            const batchPromises = batch.map(async (bankIndex) => {
                try {
                    const res = await fetch(`${origin}/yomitan/term_bank_${bankIndex}.json`, {
                        // Add internal cache tag if available in CF
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        cf: { cacheTtl: 86400, cacheEverything: true }
                    } as any);
                    if (!res.ok) return null;
                    return await res.json() as unknown[];
                } catch {
                    return null;
                }
            });

            const bankDataList = await Promise.all(batchPromises);
            let foundInBatch = false;

            for (const bankData of bankDataList) {
                if (!bankData) continue;
                for (const rawEntry of bankData) {
                    const entry = parseEntry(rawEntry as unknown[]);
                    if (entry.term === keyword || entry.reading === keyword) {
                        const res = convertToResult(entry);
                        const key = `${res.term}-${res.reading}`;
                        if (!seen.has(key)) {
                            seen.add(key);
                            results.push(res);
                            foundInBatch = true;
                        }
                    }
                }
            }

            // Optimization 2: Early Exit
            // If we found the word, we stop looking. (Assuming exact match is redundant or we only need top results)
            // If search needs complete exhaustion, remove this break. But for "hover tip", first match is usually sufficient.
            if (foundInBatch && results.length >= 1) {
                break;
            }
        }

        return NextResponse.json({
            success: true,
            keyword,
            results: results,
            source: '明鏡日汉双解辞典 (Edge Optimized)'
        }, {
            headers: {
                // Optimization 3: Aggressive Caching
                // Cache this specific keyword result for 1 hour at CDN level
                'Cache-Control': 'public, max-age=3600, s-maxage=3600, stale-while-revalidate=86400',
                'CDN-Cache-Control': 'max-age=3600'
            }
        });

    } catch (error) {
        console.error('[Yomitan API] Error:', error);
        return NextResponse.json({ error: 'Failed to search dictionary' }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';

export const runtime = 'edge';

// Constants for Edge TTS (2024/2025 updated version)
const TRUSTED_CLIENT_TOKEN = '6A5AA1D4EAFF4E9FB37E23D68491D6F4';
const CHROMIUM_FULL_VERSION = '130.0.2849.68';
// const CHROMIUM_MAJOR_VERSION = CHROMIUM_FULL_VERSION.split('.')[0];
const SEC_MS_GEC_VERSION = `1-${CHROMIUM_FULL_VERSION}`;

// Windows epoch offset (1601-01-01 to 1970-01-01) in seconds
// const WIN_EPOCH = 11644473600;

/**
 * Generate the Sec-MS-GEC token using Web Crypto API
 */
async function generateSecMsGec(): Promise<string> {
    // Current time in seconds (Unix Epoch)
    const nowSeconds = Math.floor(Date.now() / 1000);

    // Windows Epoch (1601-01-01) to Unix Epoch (1970-01-01) difference in seconds
    const unixEpochStart = 11644473600;

    // Total seconds since Windows Epoch
    let ticksSeconds = nowSeconds + unixEpochStart;

    // Round down to nearest 5 minutes (300 seconds)
    // This is the critical step for the token window validation
    ticksSeconds -= (ticksSeconds % 300);

    // Convert to 100-nanosecond intervals (Windows File Time)
    // 1 second = 10,000,000 ticks (10^7)
    // Using BigInt to prevent overflow
    const ticks = BigInt(ticksSeconds) * BigInt(10000000);

    // Trusted Client Token (Hardcoded in Edge Browser)
    const strToHash = ticks.toString() + TRUSTED_CLIENT_TOKEN;

    const encoder = new TextEncoder();
    const data = encoder.encode(strToHash);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
}

interface AlignmentData {
    charIndex: number;
    charLength?: number;
    duration?: number;
    time: number;
}

interface EdgeMetadataItem {
    Type: string;
    Data?: {
        Offset: number;
        Duration?: number;
        text?: {
            Text: string;
        };
    };
}

interface EdgeMetadataResponse {
    Metadata: EdgeMetadataItem[];
}

/**
 * Simple XML escape for SSML
 */
function escapeXml(unsafe: string): string {
    return unsafe.replace(/[<>&"']/g, (c) => {
        switch (c) {
            case '<': return '&lt;';
            case '>': return '&gt;';
            case '&': return '&amp;';
            case '"': return '&quot;';
            case "'": return '&apos;';
            default: return c;
        }
    });
}

export async function POST(req: NextRequest) {
    try {
        const { text, voice = 'ja-JP-NanamiNeural', rate = 0 } = await req.json();

        if (!text) {
            return NextResponse.json({ error: 'Text is required' }, { status: 400 });
        }

        const audioData = await generateEdgeTTS(text, voice, rate);
        return NextResponse.json(audioData);

    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : 'Internal Server Error';
        console.error('Edge TTS Error:', error);
        return NextResponse.json({ error: errorMessage }, { status: 500 });
    }
}

async function connectToEdgeTTS(wsUrl: string): Promise<WebSocket> {
    const commonHeaders = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36 Edg/130.0.0.0',
        'Origin': 'chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold',
        'Accept-Encoding': 'gzip, deflate, br',
        'Accept-Language': 'en-US,en;q=0.9',
    };

    // 1. First Attempt: Cloudflare Fetch Upgrade (Production Mode)
    try {
        console.log('[EdgeTTS] Attempting Cloudflare fetch upgrade...');
        const fetchUrl = wsUrl.replace('wss://', 'https://');
        const connectResp = await fetch(fetchUrl, {
            headers: {
                ...commonHeaders,
                'Upgrade': 'websocket',
                'Connection': 'Upgrade',
                // Note: Sec-WebSocket-Key and Version are handled by Cloudflare runtime
            }
        });

        if (connectResp.status === 101) {
            const socket = (connectResp as unknown as { webSocket: unknown }).webSocket as WebSocket;
            if (socket) {
                console.log('[EdgeTTS] Connected via Cloudflare fetch upgrade');
                // CRITICAL: Cloudflare requires calling accept() on the WebSocket object
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                if (typeof (socket as any).accept === 'function') {
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    (socket as any).accept();
                }
                return socket;
            }
        }
        console.warn(`[EdgeTTS] Cloudflare upgrade returned status: ${connectResp.status}`);
    } catch (e) {
        console.warn('[EdgeTTS] Cloudflare attempt failed, falling back to local mode:', (e as Error).message);
    }

    // 2. Second Attempt: Standard WebSocket (Local/Node.js Mode)
    console.log('[EdgeTTS] Attempting standard WebSocket connection...');
    try {
        // Try with custom headers (supported in Node.js/ws-like environments)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return new WebSocket(wsUrl, {
            headers: commonHeaders
        } as any);
    } catch (e) {
        console.warn('[EdgeTTS] Full WebSocket constructor failed, trying basic mode:', (e as Error).message);
        // Fallback for standard Web API WebSocket (no second argument for headers)
        return new WebSocket(wsUrl);
    }
}

async function generateEdgeTTS(text: string, voice: string, rate: number): Promise<{ audioBase64: string, alignment: AlignmentData[] }> {
    const secMsGec = await generateSecMsGec();
    const wsUrl = `wss://speech.platform.bing.com/consumer/speech/synthesize/readaloud/edge/v1?TrustedClientToken=${TRUSTED_CLIENT_TOKEN}&Sec-MS-GEC=${secMsGec}&Sec-MS-GEC-Version=${SEC_MS_GEC_VERSION}`;

    console.log('[EdgeTTS] Connecting to Edge TTS...');

    // Connect to WebSocket using the helper
    const ws = await connectToEdgeTTS(wsUrl);

    return new Promise((resolve, reject) => {
        const requestId = globalThis.crypto.randomUUID().replace(/-/g, '');
        const audioChunks: Uint8Array[] = [];
        const alignmentData: AlignmentData[] = [];
        let playbackFinished = false;
        let cursor = 0;

        // Message handler
        ws.addEventListener('message', async (event: any) => {
            let data = event.data;

            // Handle Blob (standard Web API)
            if (typeof Blob !== 'undefined' && data instanceof Blob) {
                data = await data.arrayBuffer();
            }

            // Handle Node.js Buffer or standard ArrayBuffer
            // In Node.js, data might be a Buffer which is a Uint8Array
            let buffer: Uint8Array | null = null;

            if (data instanceof ArrayBuffer) {
                buffer = new Uint8Array(data);
            } else if (typeof data !== 'string' && data && (data.buffer instanceof ArrayBuffer || ArrayBuffer.isView(data))) {
                // Safer check for Buffer/Uint8Array-like objects
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                buffer = new Uint8Array((data as any).buffer || data, (data as any).byteOffset || 0, (data as any).byteLength || data.length);
            }

            if (buffer) {
                if (buffer.length < 2) return;

                const headerLen = (buffer[0] << 8) | buffer[1];
                const textDecoder = new TextDecoder();
                // Ensure we don't read past buffer bounds
                if (buffer.length < 2 + headerLen) return;

                const headerText = textDecoder.decode(buffer.slice(2, 2 + headerLen));
                // console.log('[EdgeTTS] Binary Header:', headerText); // Keep minimal logs

                if (headerText.includes('Path:audio\r\n')) {
                    const audioPayload = buffer.slice(2 + headerLen);
                    audioChunks.push(new Uint8Array(audioPayload));
                }
            } else if (typeof data === 'string') {
                const message = data;
                // console.log('[EdgeTTS] Text:', message.slice(0, 50)); // Keep minimal logs

                if (message.includes('Path:audio.metadata')) {
                    const jsonParts = message.split('\r\n\r\n');
                    if (jsonParts.length > 1) {
                        try {
                            const metadata: EdgeMetadataResponse = JSON.parse(jsonParts[1]);
                            if (metadata.Metadata && metadata.Metadata.length > 0) {
                                metadata.Metadata.forEach((meta: EdgeMetadataItem) => {
                                    if (meta.Type === 'WordBoundary' && meta.Data?.text?.Text) {
                                        const word = meta.Data.text.Text;
                                        let foundIndex = text.indexOf(word, cursor);
                                        let matchLength = word.length;

                                        if (foundIndex === -1) {
                                            const numericMatch = text.slice(cursor).match(/^\s*([0-9０-９]+)/);
                                            if (numericMatch) {
                                                foundIndex = cursor;
                                                matchLength = numericMatch[0].length;
                                            }
                                        }

                                        if (foundIndex !== -1) {
                                            alignmentData.push({
                                                charIndex: foundIndex,
                                                charLength: matchLength,
                                                time: meta.Data.Offset / 10000,
                                                duration: meta.Data.Duration ? meta.Data.Duration / 10000 : undefined
                                            });
                                            cursor = foundIndex + matchLength;
                                        }
                                    }
                                });
                            }
                        } catch (e) {
                            console.error('[EdgeTTS] Metadata parse error', e);
                        }
                    }
                } else if (message.includes('Path:turn.end')) {
                    playbackFinished = true;
                    ws.close();
                }
            }
        });

        ws.addEventListener('close', () => {
            if (audioChunks.length > 0) {
                // Concatenate Chunks
                const totalLength = audioChunks.reduce((acc, chunk) => acc + chunk.length, 0);
                const fullAudio = new Uint8Array(totalLength);
                let offset = 0;
                for (const chunk of audioChunks) {
                    fullAudio.set(chunk, offset);
                    offset += chunk.length;
                }

                // Base64 Encoding
                let binary = '';
                const bytes = new Uint8Array(fullAudio);
                for (let i = 0; i < bytes.byteLength; i++) {
                    binary += String.fromCharCode(bytes[i]);
                }
                const base64 = btoa(binary);

                resolve({
                    audioBase64: base64,
                    alignment: alignmentData
                });
            } else {
                if (playbackFinished) {
                    resolve({ audioBase64: '', alignment: [] });
                } else {
                    reject(new Error('Connection closed by server without audio data'));
                }
            }
        });

        ws.addEventListener('error', (err: unknown) => {
            console.error('[EdgeTTS] WebSocket Error Details:', err);
            reject(new Error(`WebSocket connection error to ${wsUrl.slice(0, 50)}...`));
        });

        // Handler for starting the TTS protocol
        const startProtocol = () => {
            // 1. Send Speech Config
            const configMessage = `X-Timestamp:${new Date().toISOString()}\r\nContent-Type:application/json; charset=utf-8\r\nPath:speech.config\r\n\r\n` +
                JSON.stringify({
                    context: {
                        synthesis: {
                            audio: {
                                metadataOptions: {
                                    sentenceBoundaryEnabled: false,
                                    wordBoundaryEnabled: true
                                },
                                outputFormat: 'audio-24khz-48kbitrate-mono-mp3'
                            }
                        }
                    }
                });
            ws.send(configMessage);

            // 2. Send SSML
            const ratePct = Math.round(rate * 100);
            const rateStr = ratePct >= 0 ? `+${ratePct}%` : `${ratePct}%`;
            const escapedText = escapeXml(text);
            const ssml = `<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='ja-JP'>` +
                `<voice name='${voice}'>` +
                `<prosody rate='${rateStr}'>` +
                `${escapedText}` +
                `</prosody>` +
                `</voice>` +
                `</speak>`;

            const ssmlMessage = `X-RequestId:${requestId}\r\nContent-Type:application/ssml+xml\r\nX-Timestamp:${new Date().toISOString()}\r\nPath:ssml\r\n\r\n` + ssml;
            ws.send(ssmlMessage);
        };

        // If the socket is already open (common with Cloudflare fetch upgrade), send immediately
        if (ws.readyState === 1) { // 1 = OPEN
            startProtocol();
        } else {
            ws.addEventListener('open', startProtocol);
        }
    });
}

