                isDark && isSpeaking && !isPaused && "rainbow-highlight"
              )}
              style={{
                background: isSpeaking && !isPaused
                  ? (isDark ? 'rgba(251, 191, 36, 0.15)' : 'var(--bg-elevated)')
                  : (isDark ? 'rgba(255, 255, 255, 0.03)' : 'white'),
