                border: isDark && isSpeaking && !isPaused
                  ? 'none' /* Handled by rainbow-highlight */
                  : (isDark
                    ? 'none'
                    : `1px solid ${isSpeaking && !isPaused ? 'var(--border-default)' : 'var(--border-muted)'}`),
                boxShadow: !isDark && isSpeaking && !isPaused ? 'var(--shadow-sm)' : 'none'
