                  <PlayCircle className="w-10 h-10" style={{ color: 'var(--text-faint)' }} />
                </div>
                <p className="text-lg font-medium" style={{ color: 'var(--text-muted)' }}>テキストを入力してください</p>
                <p className="text-sm mt-2 max-w-xs text-center leading-relaxed">
