                    </div>

                    {/* Navigation - 機能 & Learning */}
                    <div className="flex-1 p-4 bg-transparent overflow-y-auto space-y-3">

                      {/* Functions */}
                      <div className="space-y-2">
                        <div className="grid grid-cols-2 gap-2">
                          <button
                            onClick={() => {
                              setAppMode('reader');
