import React, { useState, useRef } from 'react';
import { Search } from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { useGeminiStore } from '@/store/useGeminiStore';
import clsx from 'clsx';
import { WordToken, PartOfSpeech } from '@/types';

export default function AIChatInput() {
    const [input, setInput] = useState('');
    const { setSelectedToken, setSelectedGrammar, settings } = useAppStore();
    const { setChatOpen, isChatOpen } = useGeminiStore();
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    // Check if generating for disabling input? Maybe not needed for lookup, but good for UX if AI is busy? 
    // Actually lookup shouldn't be blocked by AI generation.
    // We'll remove isChatGenerating dependency for the input itself.

    const handleSend = () => {
        if (!input.trim()) return;

        const text = input.trim();
        setInput('');

        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
        }

        // Construct a pseudo-token for lookup
        const token: WordToken = {
            id: `manual-${Date.now()}`,
            surface: text,
            reading: '', // Will be filled by dictionary lookup if found
            romaji: '',  // Will be filled
            pos: PartOfSpeech.OTHER,
            baseForm: text,
        };

        // Clear grammar to ensure InfoPanel shows (switch from GrammarPanel)
        setSelectedGrammar(null);
        setSelectedToken(token);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSend();
        }
    };

    return (
        <div className="flex items-stretch gap-2 w-full min-w-0">
            {/* Left: Input Field Container */}
            <div className={clsx(
                "flex-1 flex items-center py-2 rounded-2xl bg-transparent backdrop-blur-xl border border-[var(--border-muted)] shadow-sm group/input transition-all min-h-[56px] min-w-0 px-4"
            )}>
                <div className="flex-1 flex items-center gap-1 min-w-0">
                    <textarea
                        ref={textareaRef}
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder="输入单词或语法进行查询..."
                        rows={1}
                        className="flex-1 h-9 py-2 resize-none bg-transparent text-base !border-none !outline-none !ring-0 !shadow-none focus:!ring-0 focus:!outline-none focus:!border-none focus-visible:!ring-0 focus-visible:!outline-none focus-visible:!border-none appearance-none floating-scrollbar placeholder:italic leading-normal min-w-0"
                        style={{
                            color: 'var(--text-primary)',
                            minHeight: '36px',
                            maxHeight: '120px'
                        }}
                    />

                    <button
                        onClick={handleSend}
                        disabled={!input.trim()}
                        className="p-2 shrink-0 rounded-xl text-[var(--scheme-accent)] hover:bg-[var(--scheme-accent-bg)] disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95"
                        title="查询"
                    >
                        <Search className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Keep the AI Chat Toggle Button as is, per user request to just decouple, not remove */}
            <button
                onClick={() => setChatOpen(true)}
                className={clsx(
                    "flex-none w-14 h-14 flex items-center justify-center rounded-2xl transition-all group/ai border border-transparent dark:border-white/10",
                    isChatOpen
                        ? "bg-transparent border-transparent shadow-[0_0_15px_rgba(0,0,0,0.3)] dark:shadow-[0_0_15px_rgba(255,255,255,0.15)]"
                        : "bg-transparent shadow-sm hover:shadow-lg hover:scale-[1.02] hover:bg-black/5 dark:hover:bg-white/5"
                )}
                title="开启全屏 AI 老师"
            >
                {/* Re-use existing icon logic if possible, or simplify. 
                 The original file had a complex SVG gradient. I will try to preserve it by NOT replacing the whole file if I can avoid it, 
                 but ReplaceFileContent works by replacing a block.
                 The block I selected (Lines 1-136) is the WHOLE file. 
                 So I need to include the SVG part back or rewrite it. 
                 I'll simplify the icon for now to avoid huge payload, 
                 OR better: I'll include the necessary imports and the simplified icon code.
                 Actually, the user liked the "AI Teacher" button. I should keep it nice.
                 I'll copy the gradient part back.
              */}
                {/* Simplified version due to complexity constraint, or trust me to copy it back? 
                  I will check line count. Original file is 136 lines. 
                  I will write the FULL content including the RainbowGradient I saw earlier.
              */}
                <div className="relative w-8 h-8 flex items-center justify-center group-hover/ai:scale-110 transition-transform duration-300">
                    {/* Simplified rainbow effect for valid TSX */}
                    <svg width="0" height="0" className="absolute pointer-events-none" aria-hidden="true">
                        <defs>
                            <linearGradient id="rainbow-gradient-icon-ref" x1="0%" y1="0%" x2="100%" y2="0%" spreadMethod="repeat">
                                <stop offset="0%" stopColor="#ff5f6d" />
                                <stop offset="50%" stopColor="#81ffb4" />
                                <stop offset="100%" stopColor="#c371ff" />
                            </linearGradient>
                        </defs>
                    </svg>

                    <div className="w-full h-full relative">
                        {/* Manual MessageSquare Icon with gradient */}
                        <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="24" height="24"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke={isChatOpen ? "url(#rainbow-gradient-icon-ref)" : "currentColor"}
                            strokeWidth="1.8"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            className="w-full h-full transition-colors"
                            style={{ color: isChatOpen ? undefined : 'var(--text-muted)' }}
                        >
                            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
                        </svg>
                    </div>
                    <div className="absolute inset-0 flex items-center justify-center pb-1">
                        <span className={clsx(
                            "font-extrabold select-none tracking-tighter leading-none text-[13px]",
                            isChatOpen ? "rainbow-text-scroll" : ""
                        )}
                            style={{ color: isChatOpen ? undefined : 'var(--text-muted)' }}
                        >
                            AI
                        </span>
                    </div>
                </div>
            </button>
        </div>
    );
}

'use client';

import React, { useRef, useEffect } from 'react';
import { useGeminiStore } from '@/store/useGeminiStore';
import { useAppStore } from '@/store/useAppStore';
import { ChevronLeft, User, Bot, Send, Trash2, Square } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

export default function AIChatView({ hideHeader = false }: { hideHeader?: boolean }) {
    const { history, isChatGenerating, setChatOpen, resetChat, cancelGeneration } = useGeminiStore();
    const settings = useAppStore(s => s.settings);
    const scrollRef = useRef<HTMLDivElement>(null);

    // Auto-scroll to bottom on new messages
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [history, isChatGenerating]);

    const [input, setInput] = React.useState('');
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    const handleSend = async () => {
        if (!input.trim() || isChatGenerating) return;
        const text = input;
        setInput('');

        // Reset height
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
        }

        await useGeminiStore.getState().sendMessage(text);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSend();
        }
    };

    // Auto-resize textarea
    useEffect(() => {
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
            textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
        }
    }, [input]);

    const handleClear = () => {
        if (window.confirm('确定要清空所有聊天记录吗？')) {
            resetChat();
        }
    };

    return (
        <div className={`flex flex-col h-full rounded-2xl shadow-sm border border-[var(--border-default)] overflow-hidden ${settings.colorScheme === 'wafu' ? 'bg-transparent' : 'glass-panel'}`}>
            {/* Header */}
            {!hideHeader && (
                <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-muted)] bg-transparent backdrop-blur-md z-10">
                    <div className="flex items-center gap-3">
                        <button
                            onClick={() => setChatOpen(false)}
                            className="p-2 -ml-2 rounded-lg hover:bg-black/5 dark:hover:bg-white/5 text-[var(--text-secondary)] transition-colors"
                        >
                            <ChevronLeft className="w-5 h-5" />
                        </button>
                        <div className="flex flex-col">
                            <h2 className="font-bold text-[var(--text-primary)] text-sm md:text-base">向 AI 日语老师提问任何关于日语学习的问题</h2>
                        </div>
                    </div>

                    <button
                        onClick={handleClear}
                        className="p-2 rounded-lg hover:bg-rose-500/10 text-[var(--text-muted)] hover:text-rose-500 transition-all group"
                        title="清空聊天记录"
                    >
                        <Trash2 className="w-4 h-4 group-hover:scale-110" />
                    </button>
                </div>
            )}

            {/* Chat Content */}
            <div
                ref={scrollRef}
                className="flex-1 overflow-y-auto p-4 space-y-6 floating-scrollbar bg-transparent"
            >
                {history.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)] gap-4">
