function GrammarPanel({ grammar, settings, isGlobalSpeaking }: { grammar: GrammarEntry; settings: AppSettings; isGlobalSpeaking: boolean }) {
    const { addGrammar, removeGrammar, isGrammarSaved } = useGrammarStore();
