'use client';

import React, { useState, useEffect, ReactNode } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, ChevronLeft, X } from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { useGeminiStore } from '@/store/useGeminiStore';
import MobileBottomBar from './MobileBottomBar';
import { MobileDrawer } from './MobileComponents';
import RefactoredInput from './RefactoredInput';

// View Types
type MobileView = 'main' | 'info' | 'ai' | 'vocab' | 'grammar';

interface MobileNavigatorProps {
    mainContent: ReactNode; // Reader
    infoContent: ReactNode; // InfoPanel
    aiContent: ReactNode;   // AIChatView
    vocabContent: ReactNode; // Vocab List
    grammarContent: ReactNode; // Grammar List
    menuContent: ReactNode; // Drawer Content
}

export default function MobileNavigator({
    mainContent,
    infoContent,
    aiContent,
    vocabContent,
    grammarContent,
    menuContent
}: MobileNavigatorProps) {
    const [currentView, setCurrentView] = useState<MobileView>('ai');
    const [hasMainLoaded, setHasMainLoaded] = useState(false);
    const [isInputModalOpen, setIsInputModalOpen] = useState(false);

    // Store access
    const { settings, selectedToken, setSelectedToken, selectedGrammar, setSelectedGrammar, inputText, setInputText, centerViewMode, setCenterViewMode } = useAppStore();
    const { isChatOpen, setChatOpen } = useGeminiStore();
    const isDark = settings.theme === 'dark';

    // Clear ghost selection on mount to prevent auto-jump
    useEffect(() => {
        useAppStore.setState({ selectedToken: null });
        // Although default is 'ai', ensuring store sync is good practice
    }, []);

    // Lazy load main content when switching to it
    useEffect(() => {
        if (currentView === 'main' && !hasMainLoaded) {
            setHasMainLoaded(true);
        }
    }, [currentView, hasMainLoaded]);

    // Sync: Selected Token/Grammar -> Info View
    useEffect(() => {
        if (selectedToken || selectedGrammar) { // Use deconstructed state
            setCurrentView('info');
        }
    }, [selectedToken, selectedGrammar]); // Use proper dependency

    // Sync: Chat Open -> AI View
    useEffect(() => {
        if (isChatOpen) {
            setCurrentView('ai');
        } else {
            // Close AI view if store says closed (e.g. from elsewhere)
            setCurrentView(v => v === 'ai' ? 'main' : v);
        }
    }, [isChatOpen]);

    // Sync: Center View Mode -> Mobile Views
    useEffect(() => {
        if (centerViewMode === 'vocab') {
            setCurrentView('vocab');
        } else if (centerViewMode === 'grammar') {
            setCurrentView('grammar');
        } else if (centerViewMode === 'reader' && (currentView === 'vocab' || currentView === 'grammar')) {
            setCurrentView('main');
        }
    }, [centerViewMode]);

    // Handle Back Navigation
    const handleBack = () => {
        const prevView = currentView;
        setCurrentView('main');

        // Reset Stores based on what we are leaving
        if (prevView === 'info') {
            setSelectedToken(null);
            setSelectedGrammar(null); // Clear grammar too
        }
        if (prevView === 'ai') {
            setChatOpen(false);
        }
        if (prevView === 'vocab' || prevView === 'grammar') {
            setCenterViewMode('reader');
        }
    };

    // Animation Variants
    const slideVariants = {
        enter: { x: '100%', opacity: 1 },
        center: { x: 0, opacity: 1 },
        exit: { x: '100%', opacity: 1 }, // Slide back to right
    };

    const transition = { type: 'spring', stiffness: 300, damping: 30 } as const;

    return (
        <div className="h-full w-full relative overflow-hidden bg-[var(--bg-base)]">

            {/* ====================
                Layer 0: Main View (Reader)
                Always rendered
               ==================== */}
            <div
                className="absolute inset-0 z-0 flex flex-col pb-16" // pb-16 for BottomBar
                style={{ overflowY: isInputModalOpen ? 'hidden' : 'auto' }}
            >
                <div className="flex-1 relative">
                    {hasMainLoaded && mainContent}
                </div>
            </div>

            {/* ====================
                Layer 1: Bottom Bar
               ==================== */}
            <MobileBottomBar
                currentView={currentView}
                onMenuClick={() => useAppStore.getState().setIsMobileDrawerOpen(true)}
                onInputClick={() => setIsInputModalOpen(true)}
                onAIClick={() => setChatOpen(true)}
            />

            {/* ====================
                Layer 2: Left Drawer (Menu)
               ==================== */}
            <MobileDrawer>
                {menuContent}
            </MobileDrawer>

            {/* ====================
                Layer 3: Input Modal (Refactored to Half-Height Sheet)
               ==================== */}
            <AnimatePresence>
                {isInputModalOpen && (
                    <>
                        {/* Backdrop */}
                        <div
                            className="fixed inset-0 z-[55] bg-black/20 backdrop-blur-sm"
                            onClick={() => setIsInputModalOpen(false)}
                        />
                        <div
                            className="absolute bottom-0 left-0 right-0 h-[60vh] z-[60] flex flex-col bg-[var(--bg-base)] shadow-[0_-8px_30px_rgba(0,0,0,0.12)] rounded-t-3xl border-t border-[var(--border-default)]"
                        >
                            <div className="flex items-center justify-between p-4 border-b border-[var(--border-default)]">
                                <h2 className="font-bold text-lg">输入文本</h2>
                                <button onClick={() => setIsInputModalOpen(false)} className="p-2 rounded-full hover:bg-[var(--bg-muted)]">
                                    <X className="w-6 h-6" />
                                </button>
                            </div>
                            <div className="flex-1 p-2 overflow-hidden">
                                <RefactoredInput
                                    inputText={inputText}
                                    setInputText={(t) => setInputText(t)}
                                    onClear={() => setInputText('')}
                                    compact={false}
                                />
                            </div>
                        </div>
                    </>
                )}
            </AnimatePresence>


            {/* ====================
                Layer 4: Full Screen Stack Pages (Info / AI)
               ==================== */}
            <AnimatePresence>
                {currentView !== 'main' && (
                    <motion.div
                        key={currentView}
                        variants={slideVariants}
                        initial="enter"
                        animate="center"
                        exit="exit"
                        transition={transition}
                        className="absolute inset-0 z-[70] bg-[var(--bg-base)] flex flex-col shadow-2xl"
                        drag="x"
                        dragConstraints={{ left: 0, right: 0 }}
                        dragElastic={{ left: 0, right: 0.5 }} // Only drag right (back)
                        dragMomentum={false}
                        onDragEnd={(e, { offset, velocity }) => {
                            // Threshold: 100px or fast swipe
                            if (offset.x > 100 || velocity.x > 500) {
                                handleBack();
                            }
                        }}
                    >
                        {/* Page Header (Navigation) - Shared custom layout */}
                        {(currentView === 'info' || currentView === 'vocab' || currentView === 'grammar' || currentView === 'ai') && (
                            <div
                                className="h-14 shrink-0 flex items-center justify-between px-4 border-b border-[var(--border-default)]"
                                style={{ background: isDark ? 'var(--bg-elevated)' : 'white' }}
                            >
                                {/* Left spacer to balance right button if needed, but here we just use justify-between */}
                                <div className="w-10" />

                                <span className="absolute left-1/2 -translate-x-1/2 font-bold text-[var(--text-primary)] text-sm md:text-base whitespace-nowrap">
                                    {currentView === 'info' && '单词详解'}
                                    {currentView === 'vocab' && '我的单词本'}
                                    {currentView === 'grammar' && '语法知识库'}
                                    {currentView === 'ai' && 'AI智能老师'}
                                </span>

                                <button
                                    onClick={handleBack}
                                    className="flex items-center gap-1 text-[var(--text-secondary)] p-2 rounded-lg active:bg-[var(--bg-muted)] transition-colors"
                                >
                                    <span className="font-medium text-sm">返回</span>
                                    <X className="w-5 h-5" />
                                </button>
                            </div>
                        )}

                        {/* Page Content */}
                        <div className="flex-1 overflow-y-auto overflow-x-hidden relative">
                            {currentView === 'info' && infoContent}
                            {currentView === 'ai' && aiContent}
                            {currentView === 'vocab' && vocabContent}
                            {currentView === 'grammar' && grammarContent}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

        </div>
    );
}

import React from 'react';
import {
    Languages,
    PlayCircle,
    PauseCircle,
    StopCircle,
    RefreshCw
} from 'lucide-react';
import clsx from 'clsx';
import { useAppStore } from '@/store/useAppStore';

interface ReaderHeaderProps {
    isTranslationVisible: boolean;
    onToggleTranslation: () => void;
    isLoadingTranslation: boolean;
    isSpeaking: boolean;
    isPaused: boolean;
    onPlay: () => void;
    onStop: () => void;
}

const ReaderHeader: React.FC<ReaderHeaderProps> = ({
    isTranslationVisible,
    onToggleTranslation,
    isLoadingTranslation,
    isSpeaking,
    isPaused,
    onPlay,
    onStop,
}) => {
    const { settings } = useAppStore();

    return (
        <div className="flex items-center gap-3 w-full h-12 px-0 shrink-0 select-none justify-center">
            {/* Left Column: Fixed Left Pair */}
            <div className="flex items-center justify-center gap-3 min-w-0 max-w-full">
                {/* Translate Button */}
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        onToggleTranslation();
                    }}
                    className={clsx(
                        "flex-1 flex items-center justify-center gap-2 px-2 rounded-2xl transition-all duration-300 h-10 whitespace-nowrap min-w-0 border border-transparent dark:border-white/10",
                        // Active State
                        isTranslationVisible
                            ? "bg-transparent border-transparent shadow-[0_0_15px_rgba(0,0,0,0.3)] dark:shadow-[0_0_15px_rgba(255,255,255,0.15)]"
                            : "bg-transparent shadow-sm hover:shadow-md hover:scale-[1.02]"
                    )}
                    style={{ color: 'var(--text-muted)' }}
                    title={isTranslationVisible ? "翻訳を闭じる" : "翻訳を表示"}
                >
                    {isLoadingTranslation ? (
                        <RefreshCw className="w-5 h-5 animate-spin" />
                    ) : (
                        <Languages className="w-5 h-5" />
                    )}
                    <span className="text-[14px] font-medium tracking-wide truncate">全文翻訳</span>
                </button>

                {/* Play/Pause Button */}
                <button
                    onClick={(e) => { e.stopPropagation(); onPlay(); }}
                    className={clsx(
                        "flex-1 flex items-center justify-center gap-2 px-2 rounded-2xl transition-all duration-300 h-10 whitespace-nowrap min-w-0 border border-transparent dark:border-white/10",
                        // Active State
                        (isSpeaking && !isPaused)
                            ? "bg-transparent border-transparent shadow-[0_0_15px_rgba(0,0,0,0.3)] dark:shadow-[0_0_15px_rgba(255,255,255,0.15)]"
                            : "bg-transparent shadow-sm hover:shadow-md hover:scale-[1.02]"
                    )}
                    style={{ color: 'var(--text-muted)' }}
                >
                    {isSpeaking && !isPaused ? (
                        <>
                            <PauseCircle className="w-5 h-5" />
                            <span className="text-[14px] font-medium tracking-wide truncate">一时停止</span>
                        </>
                    ) : (
                        <>
                            <PlayCircle className="w-5 h-5" />
                            <span className="text-[14px] font-medium tracking-wide truncate">
                                {isPaused ? "再開" : "全文朗读"}
                            </span>
                        </>
                    )}
                </button>
            </div>

            {/* Right Column: Stop Button (Conditional) */}
            <div className="flex items-center justify-start h-full">
                {(isSpeaking || isPaused) && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onStop(); }}
                        className={clsx(
                            "flex items-center justify-center gap-2 px-4 rounded-2xl transition-all duration-300 w-24 h-10 whitespace-nowrap min-w-0 border border-transparent dark:border-white/10 animate-in fade-in slide-in-from-left-2",
                            "bg-transparent shadow-sm hover:shadow-md hover:scale-[1.02]"
                        )}
                        style={{ color: 'var(--text-muted)' }}
                        title="停止"
                    >
                        <StopCircle className="w-5 h-5" />
                        <span className="text-[14px] font-medium tracking-wide">終了</span>
                    </button>
                )}
            </div>
        </div>
    );
};

export default ReaderHeader;

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';

interface ResizableThreeSectionProps {
    topContent: React.ReactNode;
    middleContent: React.ReactNode;
    bottomContent: React.ReactNode;
    initialTopHeight?: number;
    initialBottomHeight?: number;
    onTopHeightChange?: (height: number) => void;
    onBottomHeightChange?: (height: number) => void;
    minTopHeight?: number;
    minBottomHeight?: number;
    minSectionHeight?: number;
    gap?: number;
}

export default function ResizableThreeSection({
    topContent,
    middleContent,
    bottomContent,
    initialTopHeight = 200,
    initialBottomHeight = 160,
    onTopHeightChange,
    onBottomHeightChange,
    minSectionHeight = 80,
    minTopHeight,
    minBottomHeight,
    gap = 16
}: ResizableThreeSectionProps) {
    const [topHeight, setTopHeight] = useState(initialTopHeight);
    const [bottomHeight, setBottomHeight] = useState(initialBottomHeight);
    const [dragging, setDragging] = useState<'top' | 'bottom' | null>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Default specific mins to generic min if not provided
    const effectiveMinTop = minTopHeight ?? minSectionHeight;
    const effectiveMinBottom = minBottomHeight ?? minSectionHeight;

    useEffect(() => {
        setTopHeight(Math.max(initialTopHeight, effectiveMinTop));
    }, [initialTopHeight, effectiveMinTop]);

    useEffect(() => {
        setBottomHeight(Math.max(initialBottomHeight, effectiveMinBottom));
    }, [initialBottomHeight, effectiveMinBottom]);

    const handleMouseDown = useCallback((splitter: 'top' | 'bottom') => (e: React.MouseEvent) => {
        e.preventDefault();
        setDragging(splitter);
        document.body.style.cursor = 'row-resize';
        document.body.style.userSelect = 'none';
    }, []);

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!dragging || !containerRef.current) return;

            const rect = containerRef.current.getBoundingClientRect();
            const relativeY = e.clientY - rect.top;
            const containerHeight = rect.height;

            if (dragging === 'top') {
                // Dragging the first splitter (between top and middle)
                let newTopHeight = relativeY - gap / 2;

                // Ensure minimum top height
                newTopHeight = Math.max(effectiveMinTop, newTopHeight);

                // Ensure middle section has minimum height
                const remainingForMiddleAndBottom = containerHeight - newTopHeight - 2 * gap - bottomHeight;
                if (remainingForMiddleAndBottom < minSectionHeight) {
                    newTopHeight = containerHeight - 2 * gap - bottomHeight - minSectionHeight;
                }

                setTopHeight(Math.max(effectiveMinTop, newTopHeight));
            } else if (dragging === 'bottom') {
                // Dragging the second splitter (between middle and bottom)
                let newBottomHeight = containerHeight - relativeY - gap / 2;

                // Ensure minimum bottom height
                newBottomHeight = Math.max(effectiveMinBottom, newBottomHeight);

                // Ensure middle section has minimum height
                const remainingForMiddle = containerHeight - topHeight - 2 * gap - newBottomHeight;
                if (remainingForMiddle < minSectionHeight) {
                    newBottomHeight = containerHeight - topHeight - 2 * gap - minSectionHeight;
                }

                setBottomHeight(Math.max(effectiveMinBottom, newBottomHeight));
            }
        };

        const handleMouseUp = () => {
            if (dragging) {
                setDragging(null);
                document.body.style.cursor = '';
                document.body.style.userSelect = '';

                // Commit changes
                if (dragging === 'top') {
                    onTopHeightChange?.(topHeight);
                } else {
                    onBottomHeightChange?.(bottomHeight);
                }
            }
        };

        if (dragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [dragging, topHeight, bottomHeight, minSectionHeight, gap, onTopHeightChange, onBottomHeightChange]);

    return (
        <div ref={containerRef} className="flex flex-col h-full w-full relative">
            {/* Top Section */}
            <div
                style={{ height: `${topHeight}px` }}
                className="flex flex-col min-h-0 relative shrink-0"
            >
                {topContent}
            </div>

            {/* First Splitter */}
            <div
                className="cursor-row-resize z-10 flex-shrink-0 relative group flex items-center justify-center transition-colors"
                style={{ height: `${gap}px` }}
                onMouseDown={handleMouseDown('top')}
            >
                <div className="absolute top-0 bottom-0 left-0 right-0" />
                <div className="w-8 h-1 rounded-full bg-[var(--border-default)] opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            {/* Middle Section (flexible) */}
            <div
                style={{ height: `calc(100% - ${topHeight}px - ${bottomHeight}px - ${2 * gap}px)` }}
                className="flex flex-col min-h-0 relative"
            >
                {middleContent}
            </div>

            {/* Second Splitter */}
            <div
                className="cursor-row-resize z-10 flex-shrink-0 relative group flex items-center justify-center transition-colors"
                style={{ height: `${gap}px` }}
                onMouseDown={handleMouseDown('bottom')}
            >
                <div className="absolute top-0 bottom-0 left-0 right-0" />
                <div className="w-8 h-1 rounded-full bg-[var(--border-default)] opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            {/* Bottom Section */}
            <div
                style={{ height: `${bottomHeight}px` }}
                className="flex flex-col min-h-0 relative shrink-0"
            >
                {bottomContent}
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import {
    X, Type, Eye, EyeOff, Music, Server, Globe, BookOpen, Palette,
    Speaker, Languages, Sparkles, Sun, Moon, Info, RotateCcw,
    Github, Keyboard, ExternalLink
} from 'lucide-react';
import Image from 'next/image';
import { useAppStore } from '@/store/useAppStore';
import { ttsManager } from '@/lib/tts/manager';
import { PartOfSpeech, AppSettings } from '@/types';
import { COLOR_THEMES, ThemeId } from '@/lib/colorThemes';
import clsx from 'clsx';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
}

type TabId = 'appearance' | 'highlight' | 'reading' | 'audio' | 'about';

export default function SettingsModal({ isOpen, onClose }: SettingsModalProps) {
    const { settings, updateSettings, toggleSetting } = useAppStore();
    const [availableVoices, setAvailableVoices] = useState<{ id: string; name: string }[]>([]);
    const [activeTab, setActiveTab] = useState<TabId>('appearance');
    const isDark = settings.theme === 'dark';

    useEffect(() => {
        if (!isOpen) return;
        ttsManager.getVoices(settings.ttsProvider).then(voices => {
            setAvailableVoices(voices);
        });
    }, [isOpen, settings.ttsProvider]);

    if (!isOpen) return null;

    const tabs: { id: TabId; label: string; icon: React.ElementType }[] = [
        { id: 'appearance', label: '外观', icon: Palette },
        { id: 'highlight', label: '高亮', icon: Sparkles },
        { id: 'reading', label: '阅读', icon: BookOpen },
        { id: 'audio', label: '语音', icon: Speaker },
        { id: 'about', label: '关于', icon: Info },
    ];

    const handleResetSettings = () => {
        if (confirm('确定要重置所有设置为默认值吗？')) {
            localStorage.removeItem('yomi-app-store-v4');
            window.location.reload();
        }
    };

    // 通用样式
    const cardStyle = {
        background: 'var(--bg-elevated)',
        border: `1px solid var(--border-default)`,
    };

    const sectionTitleStyle = { color: 'var(--text-faint)' };
    const labelStyle = { color: 'var(--text-primary)' };
    const descStyle = { color: 'var(--text-muted)' };

    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center p-4 min-h-screen"
            style={{ background: 'rgba(0, 0, 0, 0.6)', backdropFilter: 'blur(4px)' }}
            onClick={onClose}
        >
            <div
                className="rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-200"
                style={{
                    height: '560px',
                    maxHeight: '85vh',
                    background: 'var(--bg-elevated)',
                    border: `1px solid var(--border-default)`
                }}
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header */}
                <div
                    className="flex-none flex items-center justify-between px-6 py-4"
                    style={{
                        borderBottom: `1px solid var(--border-default)`,
                        background: 'var(--bg-elevated)'
                    }}
                >
                    <h2 className="text-xl font-bold tracking-tight" style={{ color: 'var(--text-primary)' }}>设置</h2>
                    <button
                        onClick={onClose}
                        className="p-2 -mr-2 rounded-full transition-colors"
                        style={{ color: 'var(--text-muted)' }}
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Tabs */}
                <div
                    className="flex-none flex px-4 gap-1"
                    style={{
                        borderBottom: `1px solid var(--border-default)`,
                        background: 'var(--bg-elevated)'
                    }}
                >
