                                                colorScheme: isDark ? 'dark' : 'light'
                                            }}
                                            value={settings.voicevoxSpeakerId || 3}
                                            onChange={(e) => updateSettings({ voicevoxSpeakerId: parseInt(e.target.value) || 3 })}
                                        >
                                            {availableVoices.map(v => (
                                                <option key={v.id} value={v.id}>{v.name}</option>
                                            ))}
