            </div>
            <div
                className="w-11 h-6 rounded-full transition-all relative"
                style={{
                    background: checked
                        ? (isDark ? 'linear-gradient(135deg, #ec4899, #8b5cf6, #3b82f6)' : 'var(--text-primary)')
                        : (isDark ? 'var(--bg-subtle)' : 'var(--bg-subtle)'),
