import { useDictionaryStore } from '@/store/useDictionaryStore';

export class RichGrammarLoader {
    private static instance: RichGrammarLoader;
    private dictionary: Record<string, string> | null = null;
    private isOnDemandLoading = false;

    private constructor() { }

    static getInstance(): RichGrammarLoader {
        if (!RichGrammarLoader.instance) {
            RichGrammarLoader.instance = new RichGrammarLoader();
        }
        return RichGrammarLoader.instance;
    }

    async loadDictionary() {
        if (this.dictionary || this.isOnDemandLoading) return;

        const url = '/grammar/grammar_dict_zh.json';
        const cacheName = 'yomi-rich-grammar-cache-v1';

        try {
            this.isOnDemandLoading = true;
            let response: Response | undefined;
            let cache: Cache | undefined;

            if (typeof window !== 'undefined' && 'caches' in window) {
                cache = await caches.open(cacheName);
                response = await cache.match(url);
            }

            let data: any;
            if (!response) {
                console.log('[RichGrammar] Downloading dictionary...');
                response = await fetch(url);
                if (!response.ok) throw new Error(`HTTP ${response.status}`);

                const blob = await response.blob();
                useDictionaryStore.getState().addDownloadedBytes(blob.size);
                useDictionaryStore.getState().incrementDownloadedUnits();

                if (cache) {
                    await cache.put(url, new Response(blob, {
                        headers: { 'Content-Type': 'application/json' }
                    }));
                }
                data = JSON.parse(await blob.text());
            } else {
                console.log('[RichGrammar] Loading dictionary from cache...');
                const blob = await response.blob();
                useDictionaryStore.getState().addDownloadedBytes(blob.size);
                data = JSON.parse(await blob.text());
            }

            if (data) {
                this.dictionary = data;
                console.log('[Grammar] Rich dictionary loaded');
                useDictionaryStore.getState().incrementLoadedUnits();
            } else {
                console.warn('Failed to load grammar_dict_zh.json');
            }
        } catch (e) {
            console.error('Error loading rich grammar dict', e);
        } finally {
            this.isOnDemandLoading = false;
        }
    }

    async prefetch() {
        return this.loadDictionary();
    }

    getExplanation(term: string, reading?: string): string | null {
        if (!this.dictionary) return null;

        // Normalize term (remove dots, parens, tildes)
        const normalize = (s: string) => s.replace(/[（(][^）)]*[）)]/g, '')
            .replace(/[①②③④⑤⑥⑦⑧⑨⑩]/g, '')
            .replace(/[~～〜]/g, '')
            .trim();

        const cleanTerm = normalize(term);

        // 1. Exact match (Original)
        if (this.dictionary[term]) return this.dictionary[term];

        // 2. Exact match (Normalized)
        if (this.dictionary[cleanTerm]) return this.dictionary[cleanTerm];

        // 2b. Composite Title Split (Systemic Fix)
        // Handle cases like "〜を中心に・〜を中心にして・〜を中心として"
        // If full title missing, try splitting by '・' and looking up each part.
        if (term.includes('・')) {
            const parts = term.split('・');
            for (const part of parts) {
                const cleanPart = normalize(part);
                if (this.dictionary[part]) return this.dictionary[part];
                if (this.dictionary[cleanPart]) return this.dictionary[cleanPart];

                // Also try removing ~ specifically from parts even if normalize() didn't catch weird unicode
                const partNoTilde = part.replace(/[~～〜]/g, '').trim();
                if (this.dictionary[partNoTilde]) return this.dictionary[partNoTilde];
            }
        }

        // 3. Check READING (if provided) - Critical for Kanji inputs like '代わりに' -> 'かわりに'
        if (reading) {
            const cleanReading = normalize(reading);
            if (this.dictionary[reading]) return this.dictionary[reading];
            if (this.dictionary[cleanReading]) return this.dictionary[cleanReading];

            // 3b. Loose match for READING
            // Iterate keys to find if any normalized key matches the normalized reading
            const matchedReadingKey = Object.keys(this.dictionary).find(k => {
                return normalize(k) === cleanReading;
            });
            if (matchedReadingKey) return this.dictionary[matchedReadingKey];
        }

        // 4. Try to find key in dictionary that is "equivalent" after strict normalization
        // This handles cases where dictionary key has tilde but search term doesn't, or vice versa
        // We only check keys that loosely resemble the term (optimization)
        const matchedKey = Object.keys(this.dictionary).find(k => {
            // Strict check: normalized key MUST equal normalized term
            return normalize(k) === cleanTerm;
        });

        if (matchedKey) return this.dictionary[matchedKey];

        // 5. Safe partial match
        // We iterate keys to find one that is contained in the term
        // BUT strict constraint: Key must be longer than 1 character to avoid finding 'da' in 'kudasai'
        const partialKey = Object.keys(this.dictionary).find(k => {
            const cleanKey = normalize(k);
            if (cleanKey.length <= 1) return false; // Skip single chars like 'da', 'ni', 'ga'
            return cleanTerm.includes(cleanKey);
        });

        if (partialKey) return this.dictionary[partialKey];

        return null;
    }
}

export const richGrammarLoader = RichGrammarLoader.getInstance();

import { GrammarEntry } from '@/types/grammar';
import { useDictionaryStore } from '@/store/useDictionaryStore';

// 语法词典索引
const grammarIndex: Map<string, GrammarEntry[]> = new Map();
let isLoaded = false;
let loadingPromise: Promise<void> | null = null;

// 从JSON内容中提取【意味】
function extractMeaning(content: unknown[]): string {
    const text = extractPlainText(content);
    const meaningMatch = text.match(/【意味】\n?([^\n【]+)/);
    return meaningMatch ? meaningMatch[1].trim() : '';
}

// 从JSON内容中提取第一个【例文】
function extractExample(content: unknown[]): string {
    const text = extractPlainText(content);
    const exampleMatch = text.match(/【例文】\n?①([^\n②③④⑤]+)/);
    return exampleMatch ? exampleMatch[1].trim().replace(/→.+$/, '').trim() : '';
}

// 从JSON内容中提取URL
function extractUrl(content: unknown[]): string | undefined {
    for (const item of content) {
        if (typeof item === 'object' && item !== null && 'tag' in item) {
            const obj = item as { tag: string; href?: string };
            if (obj.tag === 'a' && obj.href) {
                return obj.href;
            }
        }
    }
    return undefined;
}

// 将结构化内容转为纯文本
function extractPlainText(content: unknown[]): string {
    let result = '';
    for (const item of content) {
        if (typeof item === 'string') {
            result += item;
        } else if (typeof item === 'object' && item !== null && 'content' in item) {
            const obj = item as { content: unknown };
            if (typeof obj.content === 'string') {
                result += obj.content;
            } else if (Array.isArray(obj.content)) {
                result += extractPlainText(obj.content);
            }
        }
    }
    return result;
}

// 解析单个term_bank JSON文件
async function parseTermBank(url: string): Promise<GrammarEntry[]> {
    const entries: GrammarEntry[] = [];
    const cacheName = 'yomi-grammar-cache-v1';

    try {
        let response: Response | undefined;
        let cache: Cache | undefined;

        // Try to get from Cache API first
        if (typeof window !== 'undefined' && 'caches' in window) {
            cache = await caches.open(cacheName);
            response = await cache.match(url);
        }

        let data: any;
        if (!response) {
            console.log(`[Grammar] Downloading bank ${url}...`);
            response = await fetch(url);
            if (!response.ok) return entries;

            const blob = await response.blob();
            useDictionaryStore.getState().addDownloadedBytes(blob.size);
            useDictionaryStore.getState().incrementDownloadedUnits();

            // Put into cache
            if (cache) {
                await cache.put(url, new Response(blob, {
                    headers: { 'Content-Type': 'application/json' }
                }));
            }
            data = JSON.parse(await blob.text());
        } else {
            console.log(`[Grammar] Loading bank ${url} from cache...`);
            const blob = await response.blob();
            useDictionaryStore.getState().addDownloadedBytes(blob.size);
            data = JSON.parse(await blob.text());
        }

        if (!Array.isArray(data)) return entries;

        for (const item of data) {
            if (!Array.isArray(item) || item.length < 8) continue;

            const [term, reading, title, , , definitions, , category] = item;

            if (!term || !title) continue;

            // 提取内容
            let meaning = '';
            let example = '';
            let url: string | undefined;

            if (Array.isArray(definitions) && definitions[0]) {
                const def = definitions[0];
                if (def.type === 'structured-content' && Array.isArray(def.content)) {
                    meaning = extractMeaning(def.content);
                    example = extractExample(def.content);
                    url = extractUrl(def.content);
                }
            }

            // 跳过过短或过于通用的条目
            if (term.length < 2) continue;

            entries.push({
                id: `${term}-${title}`,
                term,
                reading,
                title,
                meaning,
                example,
                category,
                url
            });
        }
    } catch (error) {
        console.error(`Failed to load grammar bank: ${url}`, error);
    }

    return entries;
}

// 加载所有语法文件
export async function loadGrammar(): Promise<void> {
    if (isLoaded) return;
    if (loadingPromise) return loadingPromise;

    loadingPromise = (async () => {
        const bankUrls = [
            '/grammar/term_bank_1.json',
            '/grammar/term_bank_2.json',
            '/grammar/term_bank_3.json',
            '/grammar/term_bank_4.json',
        ];

        const allEntries: GrammarEntry[] = [];

        console.log('[Grammar] Starting background loading...');
        for (const url of bankUrls) {
            const entries = await parseTermBank(url);
            allEntries.push(...entries);
            useDictionaryStore.getState().incrementLoadedUnits();
            // Small delay between banks
            await new Promise(resolve => setTimeout(resolve, 300));
        }

        // 构建索引：按term分组
        for (const entry of allEntries) {
            const existing = grammarIndex.get(entry.term) || [];
            // 去重：同一个title只保留一个
            if (!existing.some(e => e.title === entry.title)) {
                existing.push(entry);
                grammarIndex.set(entry.term, existing);
            }

            // 【新增】同时建立 Reading 索引 (如果 reading 和 term 不同)
            if (entry.reading && entry.reading !== entry.term) {
                const existingReading = grammarIndex.get(entry.reading) || [];
                if (!existingReading.some(e => e.title === entry.title)) {
                    existingReading.push(entry);
                    grammarIndex.set(entry.reading, existingReading);
                }
            }
        }

        isLoaded = true;
        console.log(`[Grammar] Loaded ${grammarIndex.size} unique grammar patterns`);
    })();

    return loadingPromise;
}

// 预热加载 (用于全局初始化)
export async function prefetchGrammar(): Promise<void> {
    return loadGrammar();
}

// 获取语法索引
export function getGrammarIndex(): Map<string, GrammarEntry[]> {
    return grammarIndex;
}

// 检查是否已加载
export function isGrammarLoaded(): boolean {
    return isLoaded;
}

import { GrammarMatch } from '@/types/grammar';
import { WordToken } from '@/types';
import { getGrammarIndex, loadGrammar, isGrammarLoaded } from './grammarLoader';

// 常见的语法模式关键词（优先匹配较长的）
const GRAMMAR_PATTERNS = [
    // N1级别复合语法
    'ようが', 'ようと', 'まいが', 'まいと', 'ならいざしらず', 'ともあろうものが',
    'を機に', 'に至る', 'まじき', 'ものと思われる', 'こともあって',
    // N2级别
    'おそれがある', 'ことになる', 'ことにする', 'ようにする', 'ようになる',
    'ために', 'ため', 'によって', 'において', 'に対して', 'について',
    'にとって', 'として', 'をはじめ', 'を中心に', 'に関して',
    'ばかり', 'だけ', 'しか', 'ほど', 'くらい', 'ぐらい',
    'わけ', 'はず', 'つもり', 'べき', 'ざるを得ない',
    // N3级别
    'てしまう', 'ておく', 'てある', 'ている', 'てみる', 'てくる', 'ていく',
    'ようとする', 'ことがある', 'ことができる',
    'たり', 'ながら', 'たびに', 'につれて', 'にしたがって',
    'らしい', 'ようだ', 'みたいだ', 'そうだ', 'だろう', 'でしょう',
    // 其他常见
    'という', 'といった', 'とか', 'など', 'なんか', 'なんて',
];

// 对匹配结果排序
function sortMatches(matches: GrammarMatch[]): GrammarMatch[] {
    return matches.sort((a, b) => {
        // 1. 更长的匹配词优先
        const lenDiff = b.matchedText.length - a.matchedText.length;
        if (lenDiff !== 0) return lenDiff;

        // 2. 位置更靠前的优先
        return a.position - b.position;
    });
}

// 去重：同一个语法标题只保留一个
function deduplicateMatches(matches: GrammarMatch[]): GrammarMatch[] {
    const seen = new Set<string>();
    return matches.filter(m => {
        if (seen.has(m.entry.title)) return false;
        seen.add(m.entry.title);
        return true;
    });
}

// Helper to get effective reading (Hiragana)
function getReading(token: WordToken): string {
    // WordToken.reading is Hiragana, but empty if surface is Kana-only.
    // So if reading is empty, use surface.
    return token.reading || token.surface;
}

/**
 * 在句子中匹配语法点
 * @param sentence 日语句子
 * @param maxResults 最多返回几条（默认3）
 * @param tokens (可选) 分词结果，用于更精确的读音匹配
 */
export async function matchGrammar(sentence: string, maxResults = 3, tokens?: WordToken[]): Promise<GrammarMatch[]> {
    // 确保语法库已加载
    if (!isGrammarLoaded()) {
        await loadGrammar();
    }

    const index = getGrammarIndex();
    const matches: GrammarMatch[] = [];
    const usedTitles = new Set<string>();

    const addMatch = (entry: import('@/types/grammar').GrammarEntry, matchedText: string, position: number) => {
        if (usedTitles.has(entry.title)) return;
        usedTitles.add(entry.title);
        matches.push({ entry, matchedText, position });
    };

    // 策略 A: 基于 Token 的滑动窗口匹配 (Sliding Window)
    // 解决多 Token 语法点 (如 "に比べて" = "に" + "比べて") 和 Kanji/Kana 差异
    if (tokens && tokens.length > 0) {
        const MAX_WINDOW_SIZE = 6; // 增加窗口大小以覆盖更长的语法

        for (let i = 0; i < tokens.length; i++) {
            let combinedSurface = "";
            let combinedReading = "";

            // Try increasing window sizes
            for (let j = 0; j < MAX_WINDOW_SIZE && i + j < tokens.length; j++) {
                const token = tokens[i + j];
                combinedSurface += token.surface;
                combinedReading += getReading(token);

                // 1. Check Surface (Kanji form)
                // e.g. "に比べて"
                const surfaceEntries = index.get(combinedSurface);
                if (surfaceEntries) {
                    const entry = surfaceEntries.find(e => e.meaning) || surfaceEntries[0];
                    // Strict position check
                    const pos = sentence.indexOf(combinedSurface);
                    if (pos !== -1) {
                        addMatch(entry, combinedSurface, pos);
                    }
                }

                // 2. Check Reading (Kana form)
                // e.g. "代わりに" (surface) -> "かわりに" (reading)
                // e.g. "に比べて" (surface) -> "にくらべて" (reading)
                if (combinedReading !== combinedSurface) {
                    const readingEntries = index.get(combinedReading);
                    if (readingEntries) {
                        const entry = readingEntries.find(e => e.meaning) || readingEntries[0];
                        // Highlight the *Surface* text corresponding to this reading
                        const pos = sentence.indexOf(combinedSurface);
                        if (pos !== -1) {
                            addMatch(entry, combinedSurface, pos);
                        }
                    }
                }
            }
        }
    }

    // 策略 B: 传统的字符串匹配 (用于补充，或当 Token 不可用时)
    // 依然保留，以捕获那些跨 Token 的短语 (如 "〜てしまう")
    if (matches.length < maxResults) {
        // 1. 预定义模式
        for (const pattern of GRAMMAR_PATTERNS) {
            if (matches.some(m => m.entry.title.includes(pattern))) continue;

            const pos = sentence.indexOf(pattern);
            if (pos !== -1) {
                const entries = index.get(pattern);
                if (entries && entries.length > 0) {
                    const entry = entries.find(e => e.meaning) || entries[0];
                    addMatch(entry, pattern, pos);
                }
            }
        }

        // 2. 遍历索引 (仅查找长词以避免性能问题和误判)
        // 降低优先级，最后执行
        if (matches.length < maxResults) {
            for (const [term, entries] of index) {
                if (usedTitles.has(entries[0].title)) continue;
                if (term.length < 2) continue;

                // 如果已有 Token 策略运行，这里只匹配较长的词，避免单字符/短词干扰
                if (tokens && term.length < 3) continue;

                const pos = sentence.indexOf(term);
                if (pos !== -1) {
                    const entry = entries.find(e => e.meaning) || entries[0];
                    addMatch(entry, term, pos);
                }
            }
        }
    }

    // 排序
    const sorted = sortMatches(matches);

    return sorted.slice(0, maxResults);
}

import { D1Database } from './db';

/**
 * 远程 D1 客户端
 * 通过 Cloudflare API 在本地环境操作真实的 D1 数据库
 */
export class RemoteD1Client implements D1Database {
    private apiToken: string;
    private accountId: string;
    private databaseId: string;
    private baseUrl: string;

    constructor(apiToken: string, accountId: string, databaseId: string) {
        this.apiToken = apiToken;
        this.accountId = accountId;
        this.databaseId = databaseId;
        this.baseUrl = `https://api.cloudflare.com/client/v4/accounts/${accountId}/d1/database/${databaseId}`;
    }

    private async query<T>(sql: string, params: any[] = []): Promise<any> {
        console.log(`[RemoteD1] Query: ${sql}`, params);

        try {
            const response = await fetch(`${this.baseUrl}/query`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${this.apiToken}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    sql,
                    params
                })
            });

            if (!response.ok) {
                const errorText = await response.text();
                console.error(`[RemoteD1] HTTP ${response.status} Error:`, errorText);
                throw new Error(`D1 Remote Query HTTP Error ${response.status}`);
            }

            const data = await response.json();

            if (!data.success) {
                console.error(`[RemoteD1] D1 API Error:`, data.errors);
                throw new Error(`D1 Remote Query API Error: ${data.errors?.[0]?.message || 'Unknown'}`);
            }

            // Cloudflare D1 Query API returns { result: [ { results, success, meta } ] }
            return data.result[0];
        } catch (err: any) {
            console.error(`[RemoteD1] Fetch/Query Error:`, err.message);
            throw err;
        }
    }

    prepare(query: string): any {
        return {
            bind: (...params: any[]) => ({
                first: async (colName?: string) => {
                    const result = await this.query(query, params);
                    if (!result || !result.results || result.results.length === 0) return null;
                    const row = result.results[0];
                    return colName ? row[colName] : row;
                },
                run: async () => {
                    const result = await this.query(query, params);
                    return { success: result.success, meta: result.meta };
                },
                all: async () => {
                    const result = await this.query(query, params);
                    return { results: result.results, success: result.success, meta: result.meta };
                },
                raw: async () => {
                    const result = await this.query(query, params);
                    return result.results.map((row: any) => Object.values(row));
                }
            })
        };
    }

    async batch(statements: any[]): Promise<any[]> {
        // Simple sequential implementation for now
        const results = [];
        for (const stmt of statements) {
            results.push(await stmt.run());
        }
        return results;
    }

    async exec(query: string): Promise<any> {
        return this.query(query);
    }
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface ChatMessage {
    role: 'user' | 'model';
    content: string;
    timestamp: number;
}

// Interface Update
// Interface Update
interface GeminiState {
    // Model State
    isChatGenerating: boolean;
    // Map of active generation keys to their current streaming content
    // Key: string (e.g. 'word:こんにちは'), Value: string (content)
    streamedResults: Map<string, string>;

    // Chat State
    history: ChatMessage[];
    isChatOpen: boolean;

    // Actions
    sendMessage: (text: string) => Promise<void>;
    resetChat: () => void;
    setChatOpen: (isOpen: boolean) => void;

    // Stateless generation for "AI 详解"
    // Note: onUpdate is now optional/deprecated as components should subscribe to streamedResults
    generateText: (prompt: string, systemPrompt: string, onUpdate?: (text: string) => void, options?: { temperature?: number, top_p?: number, cacheKey?: string, forceRefresh?: boolean }) => Promise<{ text: string, fromCache: boolean }>;
    cancelGeneration: (key?: string) => void;
}

// In the new architecture, we call the backend API which handles the SDK.
// The public API Key is no longer strictly needed in the frontend for these calls.

export const useGeminiStore = create<GeminiState>()(
    persist(
        (set, get) => ({
            isChatGenerating: false,
            streamedResults: new Map(),
            history: [],
            isChatOpen: false,
            // Controller for Chat ONLY. Analysis requests run in background.
            abortController: null,

            setChatOpen: (isOpen) => set({ isChatOpen: isOpen }),

            resetChat: () => set({ history: [] }),

            sendMessage: async (text) => {
                const newMessage: ChatMessage = {
                    role: 'user',
                    content: text,
                    timestamp: Date.now()
                };

                // Optimistically add user message
                set((state) => ({
                    history: [...state.history, newMessage],
                    isChatOpen: true,
                    isChatGenerating: true,
                }));

                const controller = new AbortController();
                set({ abortController: controller } as any);

                try {
                    const currentState = get();
                    const history = currentState.history;

                    const systemPrompt = `# Role
你是一位拥有20年教学经验的**专业日语导师**。你的学生是母语为中文的初学者。
你的核心任务是：不仅仅回答学生的问题，更要**主动引导**他们学习相关的背景知识、使用场景和注意事项。

# Core Rules (铁律)
1. **母语环境**：学生是**母语为中文的人**，完全理解并能流畅阅读汉字。
2. **严禁中文拼音**：禁止在任何地方出现中文拼音（Hanyu Pinyin）。严禁给中文文字标注拼音。
3. **智能注音 (日语专用)**：仅为日语汉字标注假名。汉字后紧跟括号，如：私（わたし）。
4. **简洁开场**：开场白要干脆利落。

# Output Format
请严格遵守 Markdown 格式结构进行回答。
所有回答必须简洁明了，字数严格控制在 200 字左右（除非是长难句翻译等特殊情况）。`;

                    // Construct context from history - Limit to last 4 messages (approx 2 rounds)
                    const contextMessages = history.slice(-4);
                    let contextStr = `Current Conversation Context:\n`;
                    contextMessages.forEach(msg => {
                        contextStr += `${msg.role === 'user' ? 'Student' : 'Teacher'}: ${msg.content}\n`;
                    });

                    const response = await fetch('/api/ai/chat', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            prompt: text,
                            systemPrompt: systemPrompt + "\n\n" + contextStr,
                            temperature: 0.7
                        }),
                        signal: controller.signal
                    });

                    if (response.status === 429) {
                        const data = await response.json();
                        throw new Error(data.message || '请求过于频繁，请稍后再试。');
                    }

                    if (!response.ok) {
                        throw new Error(`AI 服务暂时不可用 (${response.status})`);
                    }

                    // Create a placeholder message for the AI response
                    const aiPlaceholder: ChatMessage = {
                        role: 'model',
                        content: '',
                        timestamp: Date.now()
                    };

                    set((state) => ({
                        history: [...state.history, aiPlaceholder]
                    }));

                    const reader = response.body?.getReader();
                    const decoder = new TextDecoder();
                    let fullResponse = "";

                    if (reader) {
                        while (true) {
                            const { done, value } = await reader.read();
                            if (done) break;

                            const chunk = decoder.decode(value, { stream: true });
                            fullResponse += chunk;

                            // Update the last message progressively
                            set((state) => ({
                                history: state.history.map((msg, index) =>
                                    index === state.history.length - 1 ? { ...msg, content: fullResponse } : msg
                                )
                            }));
                        }
                    }

                } catch (error: any) {
                    if (error.name === 'AbortError') {
                        console.log("Chat Generation aborted");
                    } else {
                        console.error("Gemini Chat Error:", error);
                        set((state) => ({
                            history: [...state.history, {
                                role: 'model',
                                content: `(error: ${error.message})`,
                                timestamp: Date.now()
                            }]
                        }));
                    }
                } finally {
                    set({ isChatGenerating: false, abortController: null } as any);
                }
            },

            generateText: async (prompt, systemPrompt, onUpdate, options = { temperature: 0.85, top_p: 0.95 }) => {
                const uniqueKey = options.cacheKey || 'unknown';

                if (options.cacheKey && !options.forceRefresh) {
                    try {
                        const res = await fetch(`/api/cache?key=${encodeURIComponent(options.cacheKey)}`);
                        if (res.ok) {
                            const data = await res.json();
                            if (data.success && data.text) {
                                if (onUpdate) onUpdate(data.text);
                                return { text: data.text, fromCache: true };
                            }
                        }
                    } catch (err) {
                        console.error('[GeminiStore] Cache check failed:', err);
                    }
                }

                // 2. Concurrency Limit Check
                // We allow max 2 concurrent generations as requested
                if (get().streamedResults.size >= 2) {
                    // Optionally notify user or just throw
                    // throw new Error("同时进行的任务太多了，请稍后再试。");
                    // But better to just return error so UI can handle it
                    // Actually validation should happen before we start fetching
                }

                // If we are already generating THIS key, just return the existing stream/promise?
                // But the store doesn't keep promises. 
                // If it's in streamedResults, it's running.
                if (get().streamedResults.has(uniqueKey)) {
                    // It's already running. We generally shouldn't trigger it again.
                    // Just return an indicator? 
                    return { text: '', fromCache: false };
                }

                if (get().streamedResults.size >= 2) {
                    throw new Error("同时进行的任务已达上限 (2个)，请耐心等待之前的解读完成后再试。");
                }

                // Initialize streaming content in Map
                set((state) => {
                    const newMap = new Map(state.streamedResults);
                    newMap.set(uniqueKey, ''); // Start empty
                    return { streamedResults: newMap };
                });

                try {
                    // Note: We deliberately do NOT use an AbortController here.
                    // This allows the request to continue in the background even if the UI unmounts/switches.
                    const response = await fetch('/api/ai/chat', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            prompt,
                            systemPrompt,
                            temperature: options.temperature,
                            topP: options.top_p,
                            cacheKey: options.cacheKey
                        })
                    });

                    if (response.status === 429) throw new Error('请求过于频繁，请稍后再试。');
                    if (!response.ok) throw new Error(`AI 服务暂时不可用 (${response.status})`);

                    const contentType = response.headers.get('content-type');
                    if (contentType?.includes('application/json')) {
                        const data = await response.json();
                        if (data.success && data.text) {
                            // Update Map with final text
                            set((state) => {
                                const newMap = new Map(state.streamedResults);
                                newMap.set(uniqueKey, data.text);
                                return { streamedResults: newMap };
                            });
                            if (onUpdate) onUpdate(data.text);
                            return { text: data.text, fromCache: !!data.fromCache };
                        }
                    }

                    const reader = response.body?.getReader();
                    const decoder = new TextDecoder();
                    let fullResponse = "";
                    let buffer = "";
                    const forbiddenTerms = ["核心:", "核心：", "Core:", "用法:", "用法：", "Usage:", "避坑:", "避坑：", "Pitfalls:", "注意:", "注意：", "Note:", "总结:", "总结：", "人话解读", "人话解读：", "AI解读", "AI 详解"];

                    if (reader) {
                        while (true) {
                            const { done, value } = await reader.read();
                            if (done) break;

                            const chunk = decoder.decode(value, { stream: true });
                            buffer += chunk;

                            // ... Token processing (simplified) ...
                            let changed = true;
                            while (changed) {
                                changed = false;
                                for (const term of forbiddenTerms) {
                                    const idx = buffer.indexOf(term);
                                    if (idx !== -1) {
                                        buffer = buffer.slice(0, idx) + buffer.slice(idx + term.length);
                                        changed = true;
                                    }
                                }
                            }

                            // Update Store and Callback
                            fullResponse += buffer;

                            // CRITICAL: Update the persistent map with the accumulating response
                            set((state) => {
                                const newMap = new Map(state.streamedResults);
                                newMap.set(uniqueKey, fullResponse); // Update progressive content
                                return { streamedResults: newMap };
                            });

                            if (onUpdate) onUpdate(fullResponse);
                            buffer = "";
                        }
                    }

                    return { text: fullResponse, fromCache: false };

                } catch (error: any) {
                    console.error("Gemini Generation Error:", error);
                    throw error;
                } finally {
                    // Start a timer to remove the key from active generation map
                    // effectively marking it as "done" but keeping the result for a bit?
                    // No, invalidating it immediately means isGenerating becomes false.
                    // But we want the text to persist? 
                    // The text persists in the local component (since it receives the full text in the end).
                    // The MAP entry is chiefly for "isGenerating" check AND "current stream content".
                    // Once done, we remove it from the map.
                    // The component should handle "done" state by seeing it's not in the map anymore,
                    // BUT it should have already received the final content via onUpdate or polling.

                    set((state) => {
                        const newMap = new Map(state.streamedResults);
                        newMap.delete(uniqueKey);
                        return { streamedResults: newMap };
                    });
                }
            },

            cancelGeneration: (key?: string) => {
                if (key) {
                    set((state) => {
                        const newMap = new Map(state.streamedResults);
                        newMap.delete(key);
                        return { streamedResults: newMap };
                    });
                } else {
                    set({ streamedResults: new Map() });
                }
            }
        }),
        {
            name: 'yomi-gemini-storage', // Key for localStorage
            partialize: (state) => ({
                history: state.history,
                // Do NOT persist activeGenerations across page reloads
            }),
        }
    )
);
